`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes stdp_window.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg pre, post;  wire signed [31:0] w, xp, xq;
    stdp_synapse dut (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .post_spike(post), .learn(1'b1), .w(w), .x_pre(xp), .x_post(xq));
    integer dt, k, s, dw_p10 = 0, dw_m10 = 0;
    initial begin
        f = $fopen("stdp_window.csv", "w"); $fdisplay(f, "dt,dw");
        pre = 0; post = 0;
        for (dt = -40; dt <= 40; dt = dt + 2) begin
            rst = 1; @(posedge clk); #1 rst = 0;
            for (k = 0; k < 10; k = k + 1)
                for (s = 0; s < 100; s = s + 1) begin
                    pre = (s == 45); post = (s == 45 + dt);
                    @(posedge clk); #1;
                end
            $fdisplay(f, "%0d,%0d", dt, w - 128);
            if (dt == 10) dw_p10 = w - 128;
            if (dt == -10) dw_m10 = w - 128;
        end
        check("dw_at_plus10", dw_p10, 40);
        check("dw_at_minus10", dw_m10, -49);
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
